UPDATE t SET [dwRewardID]=r.AfterValue FROM dbo.[TQREWARDCHART] t JOIN #GfChange0 r ON t.[dwID]=r.Id WHERE NOT ((t.[dwRewardID] IS NOT NULL AND r.AfterValue IS NOT NULL AND t.[dwRewardID]=r.AfterValue) OR (t.[dwRewardID] IS NULL AND r.AfterValue IS NULL));
SET @changed=@changed+@@ROWCOUNT;
